        "credit_balance_verified", "zero_cost_guaranteed", "runner_explicitly_enabled",
    )
    if not isinstance(data, dict) or any(k not in data for k in required):
        return {"decision": "BLOCK", "reason": "missing_evidence", "may_execute": False}
